package probe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"fmt"

	"mediaroute/internal/clock"
	"mediaroute/internal/fault"
)

// MXFMagic is the 12-byte signature of the local MXF-flavoured KLV format
// generated by this project. It is intentionally distinct from SMPTE 377M
// binary partitions while preserving the UL/KLV conceptual structure.
const MXFMagic = "MXF-LOCAL-01\n"

// 16-byte SMPTE-style universal labels used as KLV keys.
var (
	ULHeaderPartition = mxfUL(0x01)
	ULPreface         = mxfUL(0x02)
	ULMaterialPackage = mxfUL(0x03)
	ULSourcePackage   = mxfUL(0x04)
	ULTrack           = mxfUL(0x05)
	ULColor           = mxfUL(0x06)
	ULCrop            = mxfUL(0x07)
	ULCodec           = mxfUL(0x08)
	ULIndexTable      = mxfUL(0x09)
	ULEssence         = mxfUL(0x0A)
	ULFooter          = mxfUL(0x0B)
)

func mxfUL(tag byte) [16]byte {
	return [16]byte{0x06, 0x0e, 0x2b, 0x34, 0x01, 0x02, 0x01, 0x01,
		0x0d, 0x01, 0x02, 0x01, 0x01, 0x00, 0x00, tag}
}

// MXFIndexEntry is one row of the MXF index table. On-wire size is 32
// bytes: index, flags, delta(ticks), reserved, offset, size.
type MXFIndexEntry struct {
	Index  uint32
	Flags  uint32 // bit 0 = key frame
	Delta  uint32 // edit-unit duration in track time-base ticks
	Offset uint64
	Size   uint64
}

// MXFKeyframe marks the key-frame bit of an index entry.
const MXFKeyframe uint32 = 1

// MXFTrackHeader is the 32-byte value of a ULTrack KLV item.
type MXFTrackHeader struct {
	TrackID      uint32
	TrackType    uint32 // 0 = video, 1 = audio
	TimeNum      uint32
	TimeDen      uint32
	Duration     uint32 // declared sample count
	Width        uint32
	Height       uint32
	Rotation     uint32 // degrees; only 0/90/180/270 accepted
}

// MXFColourWire is the 8-byte colour description payload.
type MXFColourWire struct {
	Primaries uint16
	Transfer  uint16
	Matrix    uint16
	Flags     uint16 // bit 0 = full range
}

type mxfTrackBuild struct {
	hdr    MXFTrackHeader
	colr   *Colour
	crop   *CropRect
	codec  string
	index  []MXFIndexEntry
}

// ScanMXF scans a local MXF-flavoured KLV container.
func ScanMXF(path string) (*ContainerReport, error) {
	raw, err := readBounded(path)
	if err != nil {
		return nil, err
	}
	if len(raw) < len(MXFMagic) || string(raw[:len(MXFMagic)]) != MXFMagic {
		return nil, fault.New(fault.CatTruncatedSampleTable,
			"bad MXF local-format signature")
	}
	rep := &ContainerReport{
		Format:      FormatMXF,
		Path:        path,
		InputSHA256: fmt.Sprintf("%x", sha256.Sum256(raw)),
		SizeBytes:   int64(len(raw)),
		KeyStats:    map[uint32]KeyframeStats{},
	}
	var containerColr *Colour
	pos := len(MXFMagic)
	for pos+20 <= len(raw) {
		key := [16]byte(raw[pos : pos+16])
		length := binary.BigEndian.Uint32(raw[pos+16 : pos+20])
		pos += 20
		if pos+int(length) > len(raw) {
			return nil, fault.New(fault.CatTruncatedSampleTable,
				"KLV item length %d at offset %d exceeds container",
				length, pos-20)
		}
		val := raw[pos : pos+int(length)]
		pos += int(length)
		if key == ULPreface && len(val) >= 8 {
			containerColr = decodeColour(val[:8])
		}
	}
	tracks := mxfCollectTracks(raw)
	if len(tracks) == 0 {
		return nil, fault.New(fault.CatTruncatedSampleTable, "no MXF tracks found")
	}
	for _, tb := range tracks {
		tm, ferr := tb.expand(raw, rep, containerColr)
		if ferr != nil {
			return nil, ferr
		}
		rep.KeyStats[tm.TrackID] = ComputeKeyframeStats(tm)
		rep.Tracks = append(rep.Tracks, *tm)
	}
	return rep, nil
}

func decodeColour(b []byte) *Colour {
	return &Colour{
		Primaries: binary.BigEndian.Uint16(b[0:]),
		Transfer:  binary.BigEndian.Uint16(b[2:]),
		Matrix:    binary.BigEndian.Uint16(b[4:]),
		FullRange: binary.BigEndian.Uint16(b[6:])&1 != 0,
	}
}

func decodeTrackHeader(b []byte) (MXFTrackHeader, *fault.Error) {
	if len(b) < 32 {
		return MXFTrackHeader{}, fault.New(fault.CatTruncatedSampleTable,
			"track header shorter than 32 bytes")
	}
	return MXFTrackHeader{
		TrackID:   binary.BigEndian.Uint32(b[0:]),
		TrackType: binary.BigEndian.Uint32(b[4:]),
		TimeNum:   binary.BigEndian.Uint32(b[8:]),
		TimeDen:   binary.BigEndian.Uint32(b[12:]),
		Duration:  binary.BigEndian.Uint32(b[16:]),
		Width:     binary.BigEndian.Uint32(b[20:]),
		Height:    binary.BigEndian.Uint32(b[24:]),
		Rotation:  binary.BigEndian.Uint32(b[28:]),
	}, nil
}

func decodeIndex(b []byte) MXFIndexEntry {
	return MXFIndexEntry{
		Index:  binary.BigEndian.Uint32(b[0:]),
		Flags:  binary.BigEndian.Uint32(b[4:]),
		Delta:  binary.BigEndian.Uint32(b[8:]),
		Offset: binary.BigEndian.Uint64(b[16:]),
		Size:   binary.BigEndian.Uint64(b[24:]),
	}
}

func (tb *mxfTrackBuild) expand(raw []byte, rep *ContainerReport, containerColr *Colour) (*TrackMeta, *fault.Error) {
	h := tb.hdr
	if h.TimeNum == 0 || h.TimeDen == 0 {
		return nil, fault.New(fault.CatInvalidTimeBase,
			"MXF edit rate %d/%d is invalid", h.TimeNum, h.TimeDen).
			WithTrack(h.TrackID)
	}
	if int(h.Duration) > MaxSamples {
		return nil, fault.New(fault.CatLimitExceeded,
			"sample count %d exceeds limit", h.Duration).WithTrack(h.TrackID)
	}
	if len(tb.index) < int(h.Duration) {
		return nil, fault.New(fault.CatTruncatedSampleTable,
			"index table has %d rows, track declares %d samples",
			len(tb.index), h.Duration).WithTrack(h.TrackID)
	}
	if h.Rotation != 0 && h.Rotation != 90 && h.Rotation != 180 && h.Rotation != 270 {
		return nil, fault.New(fault.CatMetadataConflict,
			"rotation %d is not a right angle", h.Rotation).WithTrack(h.TrackID)
	}
	codec := tb.codec
	if codec == "" {
		codec = "unknown"
	}
	tbmd := clock.Rational{Num: int64(h.TimeNum), Den: int64(h.TimeDen)}
	tm := &TrackMeta{
		TrackID: h.TrackID, Codec: codec, Supported: supportedCodecs[codec],
		TimeBase: tbmd, Width: h.Width, Height: h.Height,
		Rotation: int(h.Rotation), Crop: tb.crop,
		Colour: ArbitrateColour(h.TrackID, tb.colr, containerColr),
	}
	if tm.Colour.Conflict {
		rep.RecordConflict(h.TrackID, "colour",
			"track and container colour descriptions differ",
			string(tm.Colour.Source))
	}
	if tb.crop != nil {
		if e := CheckCrop(h.TrackID, h.Width, h.Height, *tb.crop); e != nil {
			return nil, e
		}
	}
	if !tm.Supported {
		rep.Faults = append(rep.Faults, fault.New(fault.CatUnsupportedCodec,
			"codec %q is not supported; only structural scan available",
			codec).WithTrack(h.TrackID))
	}
	tm.Samples = make([]SampleInfo, h.Duration)
	var ticks int64
	for i := uint32(0); i < h.Duration; i++ {
		row := tb.index[i]
		if row.Delta == 0 {
			return nil, fault.New(fault.CatInvalidTimeBase,
				"zero edit-unit delta at sample %d", i).
				WithTrack(h.TrackID).WithSample(int64(i))
		}
		end := int64(row.Offset) + int64(row.Size)
		if end > int64(len(raw)) {
			return nil, fault.New(fault.CatTruncatedSampleTable,
				"sample %d essence [%d,+%d) outside container",
				i, row.Offset, row.Size).
				WithTrack(h.TrackID).WithSample(int64(i))
		}
		nanos, e := tbmd.ToNanos(ticks)
		if e != nil {
			return nil, fault.New(fault.CatTimestampOverflow,
				"DTS overflow at sample %d", i).
				WithTrack(h.TrackID).WithSample(int64(i)).Wrap(e)
		}
		dn, e := tbmd.ToNanos(int64(row.Delta))
		if e != nil {
			return nil, fault.New(fault.CatTimestampOverflow,
				"duration overflow at sample %d", i).
				WithTrack(h.TrackID).WithSample(int64(i)).Wrap(e)
		}
		tm.Samples[i] = SampleInfo{
			Index: int64(i), Offset: int64(row.Offset), Size: int64(row.Size),
			DTSTicks: ticks, DTSNanos: nanos,
			DurationTicks: int64(row.Delta), DurationNanos: dn,
			IsKeyframe: row.Flags&MXFKeyframe != 0,
		}
		ticks += int64(row.Delta)
	}
	return tm, nil
}

// mxfCollectTracks walks the KLV items and groups per-track items in order.
func mxfCollectTracks(raw []byte) []*mxfTrackBuild {
	var out []*mxfTrackBuild
	var cur *mxfTrackBuild
	pos := len(MXFMagic)
	for pos+20 <= len(raw) {
		key := [16]byte(raw[pos : pos+16])
		length := binary.BigEndian.Uint32(raw[pos+16 : pos+20])
		pos += 20
		if pos+int(length) > len(raw) {
			return out
		}
		val := raw[pos : pos+int(length)]
		pos += int(length)
		switch key {
		case ULTrack:
			if h, e := decodeTrackHeader(val); e == nil {
				cur = &mxfTrackBuild{hdr: h}
				out = append(out, cur)
			}
		case ULColor:
			if cur != nil && len(val) >= 8 {
				cur.colr = decodeColour(val[:8])
			}
		case ULCrop:
			if cur != nil && len(val) >= 16 {
				cur.crop = &CropRect{
					Left: binary.BigEndian.Uint32(val[0:]),
					Top: binary.BigEndian.Uint32(val[4:]),
					Right: binary.BigEndian.Uint32(val[8:]),
					Bottom: binary.BigEndian.Uint32(val[12:]),
				}
			}
		case ULCodec:
			if cur != nil {
				cur.codec = string(bytes.TrimRight(val, "\x00"))
			}
		case ULIndexTable:
			if cur != nil && len(val)%32 == 0 {
				cur.index = make([]MXFIndexEntry, len(val)/32)
				for i := range cur.index {
					cur.index[i] = decodeIndex(val[i*32:])
				}
			}
		}
	}
	return out
}
